"""Which VideoToolbox encoder can actually take a frame this size.

`h264_videotoolbox` is not a software codec with a slow path: ffmpeg's wrapper
only ever binds Apple's hardware encoder, so above the size that encoder
supports `avcodec_open2` fails outright and manim falls back to `mpeg4` —
software, slow, and a visibly worse file.

Where that ceiling sits is a property of the media engine, not of the OS, and
it moves between devices. Measured with VideoToolbox directly:

    M4 Mac mini / M3 iPad Air     H.264 hardware up to 4096x2304
                                  HEVC  hardware up to 8192x4320
    iPhone 17 Pro Max             H.264 reported working at 8K

So the ceiling is asked for at run time rather than written down. Anything
H.264 cannot take in hardware goes to HEVC, which every Apple silicon media
engine encodes to 8K, and which is the codec Apple's own camera app writes.

If the probe cannot run at all — a future SDK, a stripped framework — the
answer is H.264, which is what this code did before the probe existed.
"""

from __future__ import annotations

import ctypes
import functools

__all__ = ["videotoolbox_codec", "hardware_h264_available"]

_VT_PATH = "/System/Library/Frameworks/VideoToolbox.framework/VideoToolbox"
_CF_PATH = "/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation"

_H264 = 0x61766331  # 'avc1'


def _fourcc(tag: str) -> int:
    return (ord(tag[0]) << 24) | (ord(tag[1]) << 16) | (ord(tag[2]) << 8) | ord(tag[3])


@functools.lru_cache(maxsize=1)
def _frameworks():
    vt = ctypes.CDLL(_VT_PATH)
    cf = ctypes.CDLL(_CF_PATH)

    cf.CFDictionaryCreate.restype = ctypes.c_void_p
    cf.CFDictionaryCreate.argtypes = [
        ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p),
        ctypes.POINTER(ctypes.c_void_p), ctypes.c_long,
        ctypes.c_void_p, ctypes.c_void_p,
    ]
    cf.CFRelease.argtypes = [ctypes.c_void_p]
    cf.CFBooleanGetValue.restype = ctypes.c_ubyte
    cf.CFBooleanGetValue.argtypes = [ctypes.c_void_p]

    vt.VTCompressionSessionCreate.restype = ctypes.c_int32
    vt.VTCompressionSessionCreate.argtypes = [
        ctypes.c_void_p, ctypes.c_int32, ctypes.c_int32, ctypes.c_uint32,
        ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
        ctypes.c_void_p, ctypes.c_void_p, ctypes.POINTER(ctypes.c_void_p),
    ]
    vt.VTSessionCopyProperty.restype = ctypes.c_int32
    vt.VTSessionCopyProperty.argtypes = [
        ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
        ctypes.POINTER(ctypes.c_void_p),
    ]
    vt.VTCompressionSessionInvalidate.argtypes = [ctypes.c_void_p]
    return vt, cf


@functools.lru_cache(maxsize=32)
def hardware_h264_available(width: int, height: int) -> bool:
    """Whether VideoToolbox binds a *hardware* H.264 encoder at this size.

    Asking for a session is not enough on its own — one is handed back either
    way on macOS. The answer is in
    `kVTCompressionPropertyKey_UsingHardwareAcceleratedVideoEncoder`, which the
    session refuses to report (-12900) when no hardware encoder took the job.
    """
    try:
        vt, cf = _frameworks()
        enable = ctypes.c_void_p.in_dll(
            vt, "kVTVideoEncoderSpecification_EnableHardwareAcceleratedVideoEncoder")
        true_ref = ctypes.c_void_p.in_dll(cf, "kCFBooleanTrue")
        keys = (ctypes.c_void_p * 1)(enable)
        values = (ctypes.c_void_p * 1)(true_ref)
        spec = cf.CFDictionaryCreate(
            None, keys, values, 1,
            ctypes.byref(ctypes.c_void_p.in_dll(cf, "kCFTypeDictionaryKeyCallBacks")),
            ctypes.byref(ctypes.c_void_p.in_dll(cf, "kCFTypeDictionaryValueCallBacks")))
        session = ctypes.c_void_p()
        status = vt.VTCompressionSessionCreate(
            None, int(width), int(height), _H264, spec,
            None, None, None, None, ctypes.byref(session))
        cf.CFRelease(spec)
        if status != 0 or not session:
            return False
        try:
            key = ctypes.c_void_p.in_dll(
                vt, "kVTCompressionPropertyKey_UsingHardwareAcceleratedVideoEncoder")
            out = ctypes.c_void_p()
            if vt.VTSessionCopyProperty(session, key, None, ctypes.byref(out)) != 0:
                return False
            if not out:
                return False
            using = bool(cf.CFBooleanGetValue(out))
            cf.CFRelease(out)
            return using
        finally:
            vt.VTCompressionSessionInvalidate(session)
    except Exception:
        # A probe that cannot run must not decide anything.
        return True


def videotoolbox_codec(width: int, height: int) -> tuple[str, str | None]:
    """The encoder to use at this size, and the mp4 codec tag it needs.

    HEVC in an mp4 has to be tagged `hvc1`; ffmpeg's default `hev1` is legal
    but AVFoundation and QuickTime will not play it, so the file would come out
    of a render unplayable on the device that made it.
    """
    if hardware_h264_available(width, height):
        return "h264_videotoolbox", None
    return "hevc_videotoolbox", "hvc1"
